-- Hoang An POS - canonical fresh-install schema
-- Generated by resolving every SQL migration to its final PostgreSQL state.
-- WARNING: this file deletes all application data in public. auth.users is preserved.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT ALL ON SCHEMA public TO postgres, service_role;
GRANT USAGE ON SCHEMA public TO anon, authenticated;

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
GRANT USAGE ON SCHEMA extensions TO postgres, service_role, anon, authenticated;
--
-- Name: adjust_cash_drawer_balance(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_cash_drawer_balance(cash_amount_input numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_session_id uuid;
  base_cash numeric := 0;
begin
  if auth.uid() is null or not (
    public.has_permission('cash-management.balance.adjust')
    or public.has_permission('cash-management.view-all')
    or public.is_admin(auth.uid())
  ) then
    raise exception 'Permission denied';
  end if;
  if cash_amount_input < 0 then
    raise exception 'Cash balance cannot be negative';
  end if;

  if exists (
    select 1 from public.cash_drawer_sessions
    where status = 'open' and public.requires_cash_reconciliation(cashier_id)
  ) then
    raise exception 'Close the open cash drawer before adjusting fund totals';
  end if;

  select id into target_session_id
  from public.cash_drawer_sessions
  where status = 'closed' or (status = 'open' and not public.requires_cash_reconciliation(cashier_id))
  order by (status = 'open') desc, closed_at desc, opened_at desc, id desc
  limit 1;

  if target_session_id is null then
    if cash_amount_input = 0 then
      return;
    end if;
    raise exception 'No cash drawer session is available to adjust';
  end if;

  update public.cash_drawer_sessions
  set cash_adjustment = 0
  where id is not null;

  -- Recalculate after clearing old adjustments. This keeps a manual amount
  -- stable while future cash invoices continue increasing the drawer.
  base_cash := public.current_cash_drawer_balance();

  update public.cash_drawer_sessions
  set cash_adjustment = cash_amount_input - base_cash
  where id = target_session_id;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: product_variants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_variants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    sku text NOT NULL,
    barcode text,
    base_price numeric(12,2) DEFAULT 0 NOT NULL,
    compare_at_price numeric(12,2),
    cost_price numeric(12,2) DEFAULT 0 NOT NULL,
    stock_quantity integer DEFAULT 0 NOT NULL,
    shelf_quantity integer DEFAULT 0 NOT NULL,
    weight numeric(12,3),
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT product_variants_barcode_check CHECK (((barcode IS NULL) OR (barcode ~ '^[0-9]{13}$'::text))),
    CONSTRAINT product_variants_base_price_check CHECK ((base_price >= (0)::numeric)),
    CONSTRAINT product_variants_check CHECK (((compare_at_price IS NULL) OR (compare_at_price >= base_price))),
    CONSTRAINT product_variants_check1 CHECK (((shelf_quantity >= 0) AND (shelf_quantity <= stock_quantity))),
    CONSTRAINT product_variants_cost_price_check CHECK ((cost_price >= (0)::numeric)),
    CONSTRAINT product_variants_stock_quantity_check CHECK ((stock_quantity >= 0)),
    CONSTRAINT product_variants_weight_check CHECK (((weight IS NULL) OR (weight >= (0)::numeric)))
);


--
-- Name: adjust_variant_stock(uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_variant_stock(variant_id_input uuid, quantity_delta_input integer, shelf_delta_input integer, reason_input text DEFAULT NULL::text) RETURNS public.product_variants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.product_variants; actor_name_value text;
begin
  if not (public.has_permission('products.receive-stock') or public.has_permission('warehouse.stock-out')) then
    raise exception 'Permission denied for stock adjustment';
  end if;
  select * into v from public.product_variants where id=variant_id_input for update;
  if v.id is null then raise exception 'Product variant not found'; end if;
  if v.stock_quantity + quantity_delta_input < 0 or v.shelf_quantity + shelf_delta_input < 0
     or v.shelf_quantity + shelf_delta_input > v.stock_quantity + quantity_delta_input then
    raise exception 'Invalid stock balance';
  end if;
  update public.product_variants set stock_quantity=stock_quantity+quantity_delta_input,
    shelf_quantity=shelf_quantity+shelf_delta_input, updated_at=now() where id=v.id returning * into v;
  select coalesce(full_name, auth.uid()::text) into actor_name_value from public.profiles where id=auth.uid();
  insert into public.stock_movements(variant_id,movement_type,quantity,reason,actor_id,actor_name)
  values(v.id,'adjustment',quantity_delta_input,reason_input,auth.uid(),coalesce(actor_name_value,'System'));
  return v;
end;
$$;


