CREATE TABLE public.attendance_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    clock_in_at timestamp with time zone DEFAULT now() NOT NULL,
    clock_out_at timestamp with time zone,
    work_date date DEFAULT ((now() AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date NOT NULL,
    clock_in_latitude numeric(10,7),
    clock_in_longitude numeric(10,7),
    clock_in_accuracy_m numeric(10,2),
    clock_out_latitude numeric(10,7),
    clock_out_longitude numeric(10,7),
    clock_out_accuracy_m numeric(10,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_records_clock_order_check CHECK (((clock_out_at IS NULL) OR (clock_out_at >= clock_in_at)))
);


--
-- Name: clock_in_attendance(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_in_attendance(latitude_input numeric, longitude_input numeric, accuracy_input numeric) RETURNS public.attendance_records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  attendance_record public.attendance_records;
  drawer_session public.cash_drawer_sessions;
  employee_name_value text;
  expected_cash_value numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.has_permission('attendance.clock') then
    raise exception 'Permission denied';
  end if;

  if latitude_input is null or longitude_input is null then
    raise exception 'Location is required';
  end if;

  select *
  into attendance_record
  from public.attendance_records
  where user_id = auth.uid()
    and clock_out_at is null
  order by clock_in_at desc
  limit 1;

  if found then
    null;
  else
    select *
    into attendance_record
    from public.attendance_records
    where user_id = auth.uid()
      and work_date = ((now() at time zone 'Asia/Ho_Chi_Minh')::date)
    order by clock_in_at desc
    limit 1;

    if found then
      raise exception 'Attendance for today is already completed';
    end if;

    insert into public.attendance_records (
      user_id,
      clock_in_latitude,
      clock_in_longitude,
      clock_in_accuracy_m
    )
    values (
      auth.uid(),
      latitude_input,
      longitude_input,
      accuracy_input
    )
    returning * into attendance_record;
  end if;

  if public.requires_cash_reconciliation(auth.uid()) then
    select *
    into drawer_session
    from public.cash_drawer_sessions
    where status = 'open'
    order by opened_at desc, id desc
    limit 1;

    if found then
      -- Keep attendance reconciliation identical to the drawer balance shown
      -- in the Revenue header (opening cash + cash invoices + adjustments).
      expected_cash_value := public.current_cash_drawer_balance();
    else
      select *
      into drawer_session
      from public.cash_drawer_sessions
      where status = 'closed'
      order by closed_at desc, id desc
      limit 1;

      expected_cash_value := public.current_cash_drawer_balance();
    end if;

    select coalesce(nullif(btrim(profile.full_name), ''), 'Nhân viên ' || left(profile.id::text, 8))
    into employee_name_value
    from public.profiles profile
    where profile.id = auth.uid();

    insert into public.cash_drawer_checks (
      attendance_record_id,
      employee_id,
      employee_name,
      cash_session_id,
      expected_cash
    )
    values (
      attendance_record.id,
      auth.uid(),
      coalesce(employee_name_value, 'Nhân viên'),
      drawer_session.id,
      expected_cash_value
    )
    on conflict (attendance_record_id) do nothing;
  end if;

  return attendance_record;
end;
$$;


--
-- Name: clock_out_attendance(uuid, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_out_attendance(record_id_input uuid, latitude_input numeric DEFAULT NULL::numeric, longitude_input numeric DEFAULT NULL::numeric, accuracy_input numeric DEFAULT NULL::numeric) RETURNS public.attendance_records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  attendance_record public.attendance_records;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.has_permission('attendance.clock')
    and not exists (
      select 1
      from public.attendance_records attendance
      where attendance.id = record_id_input
        and attendance.user_id = auth.uid()
        and attendance.clock_out_at is null
    ) then
    raise exception 'Permission denied';
  end if;

  if public.requires_cash_reconciliation(auth.uid())
    and exists (
      select 1
      from public.cash_drawer_sessions session
      where session.cashier_id = auth.uid()
        and session.status = 'open'
    ) then
    raise exception 'Close cash drawer before clocking out';
  end if;

  update public.attendance_records
  set
    clock_out_at = now(),
    clock_out_latitude = latitude_input,
    clock_out_longitude = longitude_input,
    clock_out_accuracy_m = accuracy_input
  where id = record_id_input
    and user_id = auth.uid()
    and clock_out_at is null
  returning * into attendance_record;

  if not found then
    raise exception 'Attendance record is not available';
  end if;

  return attendance_record;
end;
$$;


--
-- Name: cash_drawer_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_drawer_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cashier_id uuid NOT NULL,
    cashier_name text NOT NULL,
    expected_opening_cash numeric(12,2) DEFAULT 0 NOT NULL,
    opening_cash numeric(12,2) DEFAULT 0 NOT NULL,
    opening_variance numeric(12,2) DEFAULT 0 NOT NULL,
    opening_evidence_urls text[] DEFAULT '{}'::text[] NOT NULL,
    cash_sales numeric(12,2) DEFAULT 0 NOT NULL,
    transfer_sales numeric(12,2) DEFAULT 0 NOT NULL,
    expected_cash numeric(12,2) DEFAULT 0 NOT NULL,
    counted_cash numeric(12,2),
    variance numeric(12,2),
    cash_adjustment numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    close_evidence_urls text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cash_drawer_sessions_cash_sales_check CHECK ((cash_sales >= (0)::numeric)),
    CONSTRAINT cash_drawer_sessions_cashier_name_check CHECK (((char_length(cashier_name) >= 1) AND (char_length(cashier_name) <= 200))),
    CONSTRAINT cash_drawer_sessions_close_state_check CHECK ((((status = 'open'::text) AND (closed_at IS NULL) AND (counted_cash IS NULL) AND (variance IS NULL)) OR ((status = 'closed'::text) AND (closed_at IS NOT NULL) AND (counted_cash IS NOT NULL) AND (variance IS NOT NULL)))),
    CONSTRAINT cash_drawer_sessions_counted_cash_check CHECK ((counted_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_sessions_expected_cash_check CHECK ((expected_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_sessions_expected_opening_cash_check CHECK ((expected_opening_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_sessions_opening_cash_check CHECK ((opening_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_sessions_opening_variance_check CHECK ((opening_variance = (opening_cash - expected_opening_cash))),
    CONSTRAINT cash_drawer_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text]))),
    CONSTRAINT cash_drawer_sessions_transfer_sales_check CHECK ((transfer_sales >= (0)::numeric))
);


--
-- Name: close_cash_drawer(uuid, numeric, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_cash_drawer(session_id_input uuid, counted_cash_input numeric, evidence_urls_input text[] DEFAULT '{}'::text[]) RETURNS public.cash_drawer_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cash_sales_value numeric(12, 2);
  expected_cash_value numeric(12, 2);
  session_record public.cash_drawer_sessions;
  transfer_sales_value numeric(12, 2);
  variance_value numeric(12, 2);
begin
  if auth.uid() is null or not public.has_permission('cash-management.session.close') then
    raise exception 'Permission denied';
  end if;

  if counted_cash_input is null or counted_cash_input < 0 then
    raise exception 'Counted cash cannot be negative';
  end if;

  select *
  into session_record
  from public.cash_drawer_sessions
  where id = session_id_input
    and status = 'open'
    and (
      cashier_id = auth.uid()
      or public.has_permission('cash-management.view-all')
    )
  for update;

  if not found then
    raise exception 'Open cash drawer session was not found';
  end if;

  select
    coalesce(sum(total) filter (where status = 'paid' and payment_method = 'cash'), 0),
    coalesce(sum(total) filter (where status = 'paid' and payment_method = 'transfer'), 0)
  into cash_sales_value, transfer_sales_value
  from public.orders
  where cash_session_id = session_record.id;

  expected_cash_value := session_record.opening_cash + cash_sales_value;
  variance_value := counted_cash_input - (expected_cash_value + session_record.cash_adjustment);

  if variance_value <> 0 and cardinality(coalesce(evidence_urls_input, '{}')) not between 1 and 5 then
    raise exception 'Between 1 and 5 evidence images are required when cash has a variance';
  end if;

  update public.cash_drawer_sessions
  set
    cash_sales = cash_sales_value,
    transfer_sales = transfer_sales_value,
    expected_cash = expected_cash_value + session_record.cash_adjustment,
    cash_adjustment = 0,
    counted_cash = counted_cash_input,
    variance = variance_value,
    status = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    close_evidence_urls = case when variance_value = 0 then '{}' else coalesce(evidence_urls_input, '{}') end
  where public.cash_drawer_sessions.id = session_record.id
  returning * into session_record;

  return session_record;
end;
$$;


--
-- Name: create_pos_order(uuid, numeric, text, uuid, numeric, jsonb, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pos_order(cashier_id_input uuid, cash_received_input numeric, code_input text, customer_id_input uuid, discount_input numeric, items_input jsonb, note_input text, payment_method_input text, payment_proof_url_input text, payment_proof_note_input text) RETURNS public.orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item jsonb; variant_record public.product_variants; product_record public.products; batch_record public.product_batches;
  customer_record public.customers; order_record public.orders; quantity_value integer; line_total_value numeric;
  subtotal_value numeric:=0; regular_subtotal_value numeric:=0; reward_subtotal_value numeric:=0; total_value numeric:=0;
  cash_session_id_value uuid; selected_values_value jsonb; variant_name_value text; discount_value numeric:=0;
  line_discount_value numeric:=0; evaluation_items jsonb:='[]'::jsonb; promotion_match record;
  points_redeemed_value integer:=0; points_earned_value integer:=0;
begin
  if auth.uid() is null or not public.has_permission('pos.checkout') then
    raise exception 'Permission denied for checkout';
  end if;
  if cashier_id_input is distinct from auth.uid() then
    raise exception 'Cashier identity does not match the signed-in user';
  end if;
  if jsonb_typeof(items_input)<>'array' or jsonb_array_length(items_input)=0 then raise exception 'Order items are required'; end if;
  if payment_method_input not in ('cash','transfer') then raise exception 'Invalid payment method'; end if;

  if public.requires_cash_reconciliation(auth.uid()) then
    if not exists (
      select 1 from public.attendance_records attendance
      where attendance.user_id = auth.uid() and attendance.clock_out_at is null
    ) then
      raise exception 'Active attendance is required before checkout';
    end if;

    select id into cash_session_id_value
    from public.cash_drawer_sessions
    where cashier_id = auth.uid() and status = 'open'
    for update;
    if not found then raise exception 'Open a cash drawer session before checkout'; end if;
  else
    select id into cash_session_id_value
    from public.cash_drawer_sessions
    where status = 'open'
    order by opened_at desc, id desc
    limit 1
    for update;
  end if;

  if customer_id_input is not null then
    select * into customer_record from public.customers where id=customer_id_input for update;
    if customer_record.id is null then raise exception 'Customer not found'; end if;
  end if;
  for item in select value from jsonb_array_elements(items_input) loop
    quantity_value:=coalesce((item->>'quantity')::integer,0); if quantity_value<=0 then raise exception 'Invalid item quantity'; end if;
    select * into variant_record from public.product_variants where id=nullif(item->>'variant_id','')::uuid and is_active for update;
    if variant_record.id is null then raise exception 'Product variant is not available'; end if;
    select * into product_record from public.products where id=variant_record.product_id and status='active' and deleted_at is null;
    if product_record.id is null then raise exception 'Product is not available'; end if;
    if variant_record.stock_quantity<quantity_value or variant_record.shelf_quantity<quantity_value then raise exception 'Insufficient stock for selected product variant'; end if;
    if product_record.is_reward then
      if product_record.reward_points_cost<=0 then raise exception 'Reward product has invalid points cost'; end if;
      points_redeemed_value:=points_redeemed_value+(product_record.reward_points_cost*quantity_value);
      reward_subtotal_value:=reward_subtotal_value+(variant_record.base_price*quantity_value);
    else
      regular_subtotal_value:=regular_subtotal_value+(variant_record.base_price*quantity_value);
      evaluation_items:=evaluation_items||jsonb_build_array(jsonb_build_object('product_id',product_record.id,'variant_id',variant_record.id,'unit_price',variant_record.base_price,'quantity',quantity_value));
    end if;
  end loop;
  if points_redeemed_value>0 and (customer_id_input is null or customer_record.points<points_redeemed_value) then points_redeemed_value:=0; end if;
  subtotal_value:=regular_subtotal_value+case when points_redeemed_value>0 then 0 else reward_subtotal_value end;
  if coalesce(discount_input,0)<>0 then raise exception 'Order discounts are disabled'; end if;
  perform pg_advisory_xact_lock(hashtext('promotion-redemption'));
  for promotion_match in select * from public.evaluate_promotions(evaluation_items,customer_id_input,nullif(items_input->0->>'coupon_code','')) loop discount_value:=discount_value+promotion_match.discount_amount; end loop;
  discount_value:=least(discount_value,subtotal_value); total_value:=subtotal_value-discount_value;
  points_earned_value:=case when customer_id_input is null then 0 else floor(total_value/100000)::integer end;
  if payment_method_input='cash' and coalesce(cash_received_input,0)<total_value then raise exception 'Cash received is lower than total'; end if;
  if payment_method_input='transfer'
    and nullif(trim(coalesce(payment_proof_url_input,'')), '') is null
    and nullif(trim(coalesce(payment_proof_note_input,'')), '') is null then
    raise exception 'Payment proof is required for transfer orders';
  end if;
  insert into public.orders(code,customer_id,cash_session_id,cashier_id,cashier_name,subtotal,discount,total,payment_method,cash_received,change_amount,payment_proof_url,payment_proof_note,note,status,points_earned,points_redeemed)
  values(code_input,customer_id_input,cash_session_id_value,auth.uid(),(select full_name from public.profiles where id=auth.uid()),subtotal_value,discount_value,total_value,
    payment_method_input,case when payment_method_input='cash' then coalesce(cash_received_input,0) else total_value end,case when payment_method_input='cash' then coalesce(cash_received_input,0)-total_value else 0 end,
    payment_proof_url_input,payment_proof_note_input,note_input,'paid',points_earned_value,points_redeemed_value) returning * into order_record;
  for item in select value from jsonb_array_elements(items_input) loop
    quantity_value:=(item->>'quantity')::integer; batch_record:=null;
    select * into variant_record from public.product_variants where id=(item->>'variant_id')::uuid for update;
    select * into product_record from public.products where id=variant_record.product_id;
    if nullif(item->>'batch_id','') is not null then select * into batch_record from public.product_batches where id=(item->>'batch_id')::uuid and variant_id=variant_record.id for update; end if;
    perform public.reserve_variant_stock(variant_record.id,quantity_value,nullif(item->>'batch_id','')::uuid);
    select coalesce(jsonb_object_agg(a.name,v.label),'{}'::jsonb), string_agg(v.label,' / ' order by a.sort_order)
      into selected_values_value,variant_name_value from public.variant_value_links l join public.product_variant_values v on v.id=l.variant_value_id
      join public.product_variant_attributes a on a.id=l.variant_attribute_id where l.variant_id=variant_record.id;
    line_discount_value:=case when product_record.is_reward or regular_subtotal_value<=0 then 0 else round(discount_value*(variant_record.base_price*quantity_value/regular_subtotal_value),2) end;
    line_total_value:=case when product_record.is_reward and points_redeemed_value>0 then 0 else variant_record.base_price*quantity_value-line_discount_value end;
    insert into public.order_items(order_id,product_id,variant_id,batch_id,product_name,variant_name,selected_values,sku,quantity,unit_price,discount_amount,final_price,line_total,reward_points_cost,import_date,expiry_date)
    values(order_record.id,product_record.id,variant_record.id,nullif(item->>'batch_id','')::uuid,product_record.name,variant_name_value,selected_values_value,variant_record.sku,
      quantity_value,case when product_record.is_reward and points_redeemed_value>0 then 0 else variant_record.base_price end,line_discount_value,
      case when product_record.is_reward and points_redeemed_value>0 then 0 else greatest(variant_record.base_price-(line_discount_value/quantity_value),0) end,
      line_total_value,case when product_record.is_reward and points_redeemed_value>0 then product_record.reward_points_cost else 0 end,batch_record.import_date,batch_record.expiry_date);
    insert into public.stock_movements(variant_id,movement_type,quantity,reason,reference_type,reference_id,actor_id,actor_name)
    values(variant_record.id,'sale',-quantity_value,'POS sale','order',order_record.id,auth.uid(),coalesce((select full_name from public.profiles where id=auth.uid()),'System'));
  end loop;
  for promotion_match in select * from public.evaluate_promotions(evaluation_items,customer_id_input,nullif(items_input->0->>'coupon_code','')) loop
    insert into public.promotion_redemptions(promotion_id,user_id,order_id,discount_amount) values(promotion_match.promotion_id,customer_id_input,order_record.id,promotion_match.discount_amount);
  end loop;
  if customer_id_input is not null then update public.customers set points=points-points_redeemed_value+points_earned_value where id=customer_id_input; end if;
  insert into public.order_audit_events(order_id,actor_id,event_type,details) values(order_record.id,auth.uid(),'created',jsonb_build_object('code',order_record.code,'total',order_record.total,'points_earned',points_earned_value,'points_redeemed',points_redeemed_value));
  return order_record;
end;
$$;


--
-- Name: current_cash_drawer_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_cash_drawer_balance() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with latest_open as (
    select session.*
    from public.cash_drawer_sessions session
    where session.status = 'open'
    order by session.opened_at desc, session.id desc
    limit 1
  ),
  latest_closed as (
    select session.*
    from public.cash_drawer_sessions session
    where session.status = 'closed'
    order by session.closed_at desc, session.id desc
    limit 1
  )
  select coalesce(
    (
      select opened.opening_cash
        + opened.cash_adjustment
        + coalesce((
          select sum(pos_order.total)
          from public.orders pos_order
          where pos_order.cash_session_id = opened.id
            and pos_order.status = 'paid'
            and pos_order.payment_method = 'cash'
        ), 0)
      from latest_open opened
    ),
    (
      select coalesce(closed.counted_cash, closed.expected_cash, 0)
        + closed.cash_adjustment
        + coalesce((
          select sum(pos_order.total)
          from public.orders pos_order
          where pos_order.cash_session_id is null
            and pos_order.status = 'paid'
            and pos_order.payment_method = 'cash'
            and pos_order.created_at > closed.closed_at
        ), 0)
      from latest_closed closed
    ),
    (
      select coalesce(sum(pos_order.total), 0)
      from public.orders pos_order
      where pos_order.cash_session_id is null
        and pos_order.status = 'paid'
        and pos_order.payment_method = 'cash'
    ),
    0
  )::numeric;
$$;


--
-- Name: delete_attendance_record(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_attendance_record(record_id_input uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.has_permission('attendance.history.delete') then
    raise exception 'Permission denied';
  end if;

  delete from public.attendance_records
  where id = record_id_input
    and (
      user_id = auth.uid()
      or public.has_permission('attendance.history.view-all')
    );

  if not found then
    raise exception 'Attendance record is not available';
  end if;
end;
$$;


--
-- Name: delete_cash_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_cash_reconciliation(check_id_input uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  check_record public.cash_drawer_checks;
begin
  if auth.uid() is null or not public.has_permission('cash-management.reconciliation.delete') then
    raise exception 'Permission denied';
  end if;

  select * into check_record
  from public.cash_drawer_checks
  where id = check_id_input
  for update;

  if not found then
    raise exception 'Cash reconciliation was not found';
  end if;

  delete from public.cash_drawer_checks where id = check_record.id;
end;
$$;


--
-- Name: delete_pos_orders(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_pos_orders(order_ids_input uuid[], reason_input text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare order_id_value uuid; order_record public.orders; deleted_count integer:=0;
begin
  if auth.uid() is null or not public.has_permission('orders.delete') then raise exception 'Permission denied'; end if;
  if nullif(trim(coalesce(reason_input,'')), '') is null then raise exception 'Deletion reason is required'; end if;
  foreach order_id_value in array order_ids_input loop
    select * into order_record from public.orders where id=order_id_value;
    if order_record.id is null then continue; end if;
    if order_record.status='paid' then perform public.cancel_pos_order(order_id_value,coalesce(nullif(trim(reason_input),''),'Delete order')); end if;
    delete from public.orders where id=order_id_value; deleted_count:=deleted_count+1;
  end loop;
  return deleted_count;
end;
$$;


--
-- Name: ensure_default_product_variant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_default_product_variant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.product_variants(product_id, sku, is_default)
  values (new.id, 'DEFAULT-' || upper(substr(replace(new.id::text, '-', ''), 1, 12)), true);
  return new;
end;
$$;


--
-- Name: evaluate_promotions(jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_promotions(items_input jsonb, customer_id_input uuid DEFAULT NULL::uuid, coupon_code_input text DEFAULT NULL::text) RETURNS TABLE(promotion_id uuid, name text, discount_amount numeric, free_shipping boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p public.promotions; subtotal_value numeric; scoped_value numeric; amount_value numeric;
begin
  select coalesce(sum((i->>'unit_price')::numeric * (i->>'quantity')::integer),0)
  into subtotal_value from jsonb_array_elements(items_input) i;
  for p in select * from public.promotions x where x.is_active
    and (x.start_at is null or x.start_at <= now()) and (x.end_at is null or x.end_at > now())
    and (x.trigger_type='automatic' or
         (x.trigger_type='coupon' and upper(x.code)=upper(trim(coupon_code_input))))
    order by x.priority desc, x.created_at
  loop
    if p.total_usage_limit is not null and (select count(*) from public.promotion_redemptions r where r.promotion_id=p.id) >= p.total_usage_limit then continue; end if;
    if p.usage_per_customer is not null and customer_id_input is null then continue; end if;
    if customer_id_input is not null and p.usage_per_customer is not null and
       (select count(*) from public.promotion_redemptions r where r.promotion_id=p.id and r.user_id=customer_id_input) >= p.usage_per_customer then continue; end if;
    if exists (select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type='order_total'
      and not case c.operator when 'gte' then subtotal_value >= (c.value#>>'{}')::numeric when 'gt' then subtotal_value > (c.value#>>'{}')::numeric
      when 'lte' then subtotal_value <= (c.value#>>'{}')::numeric when 'lt' then subtotal_value < (c.value#>>'{}')::numeric
      when 'eq' then subtotal_value = (c.value#>>'{}')::numeric when 'neq' then subtotal_value <> (c.value#>>'{}')::numeric else false end) then continue; end if;
    if exists (select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type='quantity'
      and not case c.operator
        when 'gte' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) >= (c.value#>>'{}')::integer
        when 'gt' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) > (c.value#>>'{}')::integer
        when 'lte' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) <= (c.value#>>'{}')::integer
        when 'lt' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) < (c.value#>>'{}')::integer
        when 'eq' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) = (c.value#>>'{}')::integer
        when 'neq' then (select coalesce(sum((i->>'quantity')::integer),0) from jsonb_array_elements(items_input) i) <> (c.value#>>'{}')::integer else false end) then continue; end if;
    if customer_id_input is null and exists(select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type in ('customer_order_count','customer_points')) then continue; end if;
    if exists (select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type='customer_order_count'
      and not case c.operator
        when 'eq' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') = (c.value#>>'{}')::integer
        when 'neq' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') <> (c.value#>>'{}')::integer
        when 'gt' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') > (c.value#>>'{}')::integer
        when 'gte' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') >= (c.value#>>'{}')::integer
        when 'lt' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') < (c.value#>>'{}')::integer
        when 'lte' then (select count(*) from public.orders o where o.customer_id=customer_id_input and o.status='paid') <= (c.value#>>'{}')::integer else false end) then continue; end if;
    if exists (select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type='customer_points'
      and not case c.operator
        when 'eq' then (select points from public.customers where id=customer_id_input) = (c.value#>>'{}')::integer
        when 'neq' then (select points from public.customers where id=customer_id_input) <> (c.value#>>'{}')::integer
        when 'gt' then (select points from public.customers where id=customer_id_input) > (c.value#>>'{}')::integer
        when 'gte' then (select points from public.customers where id=customer_id_input) >= (c.value#>>'{}')::integer
        when 'lt' then (select points from public.customers where id=customer_id_input) < (c.value#>>'{}')::integer
        when 'lte' then (select points from public.customers where id=customer_id_input) <= (c.value#>>'{}')::integer else false end) then continue; end if;
    if exists (select 1 from public.promotion_conditions c where c.promotion_id=p.id and c.condition_type not in ('order_total','quantity','customer_order_count','customer_points')) then continue; end if;
    select coalesce(sum((i->>'unit_price')::numeric*(i->>'quantity')::integer),0) into scoped_value
    from jsonb_array_elements(items_input) i where
      exists(select 1 from public.promotion_scopes s where s.promotion_id=p.id and s.scope_type='all') or
      exists(select 1 from public.promotion_scopes s where s.promotion_id=p.id and s.scope_type='variant' and s.scope_id=(i->>'variant_id')::uuid) or
      exists(select 1 from public.promotion_scopes s where s.promotion_id=p.id and s.scope_type='product' and s.scope_id=(i->>'product_id')::uuid) or
      exists(select 1 from public.promotion_scopes s join public.products pr on pr.id=(i->>'product_id')::uuid
        where s.promotion_id=p.id and s.scope_type='category'
          and (pr.product_type_id=s.scope_id or pr.category_id=s.scope_id));
    if scoped_value <= 0 then continue; end if;
    amount_value := case p.discount_type when 'percentage' then scoped_value*p.discount_value/100 when 'fixed_amount' then least(scoped_value,p.discount_value) else 0 end;
    if p.max_discount_amount is not null then amount_value:=least(amount_value,p.max_discount_amount); end if;
    promotion_id:=p.id; name:=p.name; discount_amount:=round(amount_value,2); free_shipping:=p.discount_type='free_shipping'; return next;
    if not p.is_stackable then return; end if;
  end loop;
end;
$$;


--
-- Name: cash_drawer_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_drawer_checks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attendance_record_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    employee_name text NOT NULL,
    cash_session_id uuid,
    expected_cash numeric(12,2) DEFAULT 0 NOT NULL,
    actual_cash numeric(12,2),
    is_match boolean,
    evidence_urls text[] DEFAULT '{}'::text[] NOT NULL,
    checked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cash_drawer_checks_actual_cash_check CHECK ((actual_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_checks_employee_name_check CHECK (((char_length(employee_name) >= 1) AND (char_length(employee_name) <= 200))),
    CONSTRAINT cash_drawer_checks_expected_cash_check CHECK ((expected_cash >= (0)::numeric)),
    CONSTRAINT cash_drawer_checks_result_check CHECK ((((checked_at IS NULL) AND (actual_cash IS NULL) AND (is_match IS NULL) AND (cardinality(evidence_urls) = 0)) OR ((checked_at IS NOT NULL) AND (actual_cash IS NOT NULL) AND (is_match = (actual_cash = expected_cash)) AND (is_match OR ((cardinality(evidence_urls) >= 1) AND (cardinality(evidence_urls) <= 5))))))
);


--
-- Name: get_attendance_cash_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attendance_cash_check(attendance_record_id_input uuid) RETURNS public.cash_drawer_checks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  check_record public.cash_drawer_checks;
begin
  select cash_check.*
  into check_record
  from public.cash_drawer_checks cash_check
  join public.attendance_records attendance on attendance.id = cash_check.attendance_record_id
  where cash_check.attendance_record_id = attendance_record_id_input
    and (
      attendance.user_id = auth.uid()
      or public.has_permission('attendance.history.view-all')
      or public.has_permission('cash-management.view-all')
    )
  limit 1;

  if not found then
    return null;
  end if;

  -- Pending checks always show the same live drawer amount as the Revenue
  -- header. Completed historical checks remain immutable.
  if check_record.checked_at is null then
    update public.cash_drawer_checks
    set expected_cash = public.current_cash_drawer_balance(),
        cash_session_id = (
          select session.id
          from public.cash_drawer_sessions session
          where session.status = 'open'
          order by session.opened_at desc, session.id desc
          limit 1
        )
    where id = check_record.id
    returning * into check_record;
  end if;

  return check_record;
end;
$$;


--
-- Name: get_attendance_cash_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attendance_cash_session(attendance_record_id_input uuid) RETURNS public.cash_drawer_sessions
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select session.*
  from public.cash_drawer_checks cash_check
  join public.attendance_records attendance on attendance.id = cash_check.attendance_record_id
  join public.cash_drawer_sessions session on session.id = cash_check.cash_session_id
  where cash_check.attendance_record_id = attendance_record_id_input
    and (
      attendance.user_id = auth.uid()
      or public.has_permission('attendance.history.view-all')
      or public.has_permission('cash-management.view-all')
    )
  limit 1;
$$;


--
-- Name: get_cash_drawer_handover(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_drawer_handover() RETURNS TABLE(expected_opening_cash numeric, has_open_session boolean, is_first_session boolean, open_cashier_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.has_permission('cash-management') then
    raise exception 'Permission denied';
  end if;

  return query
  select
    public.current_cash_drawer_balance()::numeric as expected_opening_cash,
    exists (
      select 1
      from public.cash_drawer_sessions open_session
      where open_session.status = 'open'
    ) as has_open_session,
    not exists (
      select 1
      from public.cash_drawer_sessions any_session
      where any_session.status = 'closed'
    ) as is_first_session,
    (
      select open_session.cashier_name
      from public.cash_drawer_sessions open_session
      where open_session.status = 'open'
      order by open_session.opened_at desc
      limit 1
    ) as open_cashier_name;
end;
$$;


--
-- Name: guard_product_engine_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_product_engine_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_table_name = 'products'
    and tg_op = 'UPDATE'
    and public.has_permission('products.toggle-active')
    and (
      to_jsonb(new) - array['status', 'updated_at']
      = to_jsonb(old) - array['status', 'updated_at']
    ) then
    return new;
  elsif tg_table_name = 'products'
    and tg_op = 'UPDATE'
    and public.has_permission('cloudinary-images.delete')
    and (
      to_jsonb(new) - array['image_url', 'updated_at']
      = to_jsonb(old) - array['image_url', 'updated_at']
    ) then
    return new;
  elsif tg_table_name = 'product_variant_values'
    and tg_op = 'UPDATE'
    and public.has_permission('cloudinary-images.delete')
    and (
      to_jsonb(new) - array['metadata', 'updated_at']
      = to_jsonb(old) - array['metadata', 'updated_at']
    ) then
    return new;
  elsif tg_table_name = 'product_images'
    and tg_op = 'DELETE'
    and public.has_permission('cloudinary-images.delete') then
    return old;
  elsif tg_table_name = 'products' then
    if tg_op = 'INSERT' and not public.has_permission('products.create') then
      raise exception 'Permission denied for product create';
    elsif tg_op = 'UPDATE' then
      if new.deleted_at is not null and old.deleted_at is null then
        if not public.has_permission('products.delete') then
          raise exception 'Permission denied for product delete';
        end if;
      elsif not public.has_permission('products.update') then
        raise exception 'Permission denied for product update';
      end if;
    elsif tg_op = 'DELETE' and not public.has_permission('products.delete') then
      raise exception 'Permission denied for product delete';
    end if;
  elsif tg_table_name = 'product_categories' then
    if not (
      public.has_permission('products.update')
      or public.has_permission('products.types.manage')
      or (tg_op in ('INSERT','UPDATE') and public.has_permission('products.categories.create'))
    ) then
      raise exception 'Permission denied for product category';
    end if;
  elsif tg_table_name in ('product_types', 'product_type_attributes') then
    if not (public.has_permission('products.update') or public.has_permission('products.types.manage')) then
      raise exception 'Permission denied for product configuration';
    end if;
  elsif tg_table_name = 'product_attributes' then
    if not (public.has_permission('products.update') or public.has_permission('products.attributes.manage')) then
      raise exception 'Permission denied for product attributes';
    end if;
  elsif tg_table_name = 'product_variants'
    and tg_op = 'UPDATE'
    and (
      public.has_permission('pos.checkout')
      or public.has_permission('orders.cancel')
      or public.has_permission('products.receive-stock')
      or public.has_permission('warehouse.stock-out')
      or public.has_permission('inventory.submit')
    )
    and (
      to_jsonb(new) - array['stock_quantity', 'shelf_quantity', 'updated_at']
      = to_jsonb(old) - array['stock_quantity', 'shelf_quantity', 'updated_at']
    ) then
    return new;
  elsif tg_op = 'INSERT' then
    if not (public.has_permission('products.create') or public.has_permission('products.update')) then
      raise exception 'Permission denied for product data create';
    end if;
  elsif not public.has_permission('products.update') then
    raise exception 'Permission denied for product data update';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, full_name, phone, role, is_active)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.email, new.phone),
    new.phone,
    'staff',
    false
  )
  on conflict (id) do nothing;

  update public.profiles p
  set role_id = r.id
  from public.app_roles r
  where p.id = new.id
    and p.role_id is null
    and r.code = p.role;

  return new;
end;
$$;


--
-- Name: has_permission(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(permission_key text, user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    left join public.app_roles r on r.id = p.role_id
    where p.id = user_id
      and user_id = auth.uid()
      and p.is_active = true
      and (
        public.is_admin(user_id)
        or (
          r.is_active = true
          and permission_key = any(coalesce(r.permissions, '{}'))
        )
      )
  );
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    left join public.app_roles r on r.id = p.role_id
    where p.id = user_id
      and user_id = auth.uid()
      and p.is_active = true
      and (
        p.role = 'admin'
        or r.code = 'admin'
        or (
          user_id = auth.uid()
          and coalesce(auth.jwt() -> 'app_metadata' ->> 'role', '') = 'admin'
        )
      )
      and coalesce(r.is_active, true) = true
  );
$$;


