);


--
-- Name: issue_product_stock(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_product_stock(product_id_input uuid, quantity_input integer, reason_input text) RETURNS public.products
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare variant_record public.product_variants; product_record public.products;
begin
  if not public.has_permission('warehouse.stock-out') then raise exception 'Permission denied for stock out'; end if;
  select * into variant_record from public.product_variants where product_id=product_id_input and is_active for update;
  if (select count(*) from public.product_variants where product_id=product_id_input and is_active)<>1 then raise exception 'Choose a SKU in Product editor for multi-variant stock'; end if;
  if variant_record.stock_quantity<quantity_input then raise exception 'Insufficient stock'; end if;
  update public.product_variants set stock_quantity=stock_quantity-quantity_input,shelf_quantity=greatest(shelf_quantity-quantity_input,0),updated_at=now() where id=variant_record.id;
  insert into public.stock_movements(variant_id,movement_type,quantity,reason,actor_id,actor_name) values(variant_record.id,'out',-quantity_input,reason_input,auth.uid(),coalesce((select full_name from public.profiles where id=auth.uid()),'System'));
  select * into product_record from public.products where id=product_id_input; return product_record;
end;
$$;


--
-- Name: issue_variant_stock(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_variant_stock(variant_id_input uuid, quantity_input integer, reason_input text) RETURNS public.product_variants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare variant_record public.product_variants;
begin
  if not public.has_permission('warehouse.stock-out') then
    raise exception 'Permission denied for stock issue';
  end if;
  if quantity_input <= 0 then raise exception 'Quantity must be greater than zero'; end if;
  if nullif(trim(reason_input),'') is null then raise exception 'Stock issue reason is required'; end if;

  select * into variant_record
  from public.product_variants
  where id = variant_id_input and is_active
  for update;
  if variant_record.id is null then raise exception 'Product variant not found'; end if;
  if variant_record.stock_quantity < quantity_input then raise exception 'Insufficient stock'; end if;

  update public.product_variants
  set stock_quantity = stock_quantity - quantity_input, updated_at = now()
  where id = variant_record.id returning * into variant_record;

  insert into public.stock_movements(variant_id,movement_type,quantity,reason,actor_id,actor_name)
  values(variant_record.id,'out',-quantity_input,left(trim(reason_input),1000),auth.uid(),coalesce((select full_name from public.profiles where id=auth.uid()),'Hệ thống'));
  return variant_record;
end;
$$;


--
-- Name: list_attendance_history(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_attendance_history(month_start_input date) RETURNS TABLE(id uuid, user_id uuid, employee_name text, clock_in_at timestamp with time zone, clock_out_at timestamp with time zone, work_date date, clock_in_latitude numeric, clock_in_longitude numeric, clock_in_accuracy_m numeric, clock_out_latitude numeric, clock_out_longitude numeric, clock_out_accuracy_m numeric, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.has_permission('attendance.history.view-all') then
    raise exception 'Permission denied';
  end if;

  return query
  select
    attendance.id,
    attendance.user_id,
    coalesce(nullif(btrim(profile.full_name), ''), 'Nhân viên ' || left(profile.id::text, 8)),
    attendance.clock_in_at,
    attendance.clock_out_at,
    attendance.work_date,
    attendance.clock_in_latitude,
    attendance.clock_in_longitude,
    attendance.clock_in_accuracy_m,
    attendance.clock_out_latitude,
    attendance.clock_out_longitude,
    attendance.clock_out_accuracy_m,
    attendance.created_at,
    attendance.updated_at
  from public.attendance_records attendance
  join public.profiles profile on profile.id = attendance.user_id
  where attendance.work_date >= date_trunc('month', month_start_input)::date
    and attendance.work_date < (date_trunc('month', month_start_input) + interval '1 month')::date
  order by profile.full_name nulls last, attendance.work_date;
end;
$$;


--
-- Name: list_cash_drawer_sessions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cash_drawer_sessions(limit_input integer DEFAULT 100) RETURNS TABLE(id uuid, cashier_id uuid, cashier_name text, expected_opening_cash numeric, opening_cash numeric, opening_variance numeric, opening_evidence_urls text[], cash_sales numeric, transfer_sales numeric, expected_cash numeric, counted_cash numeric, variance numeric, status text, opened_at timestamp with time zone, closed_at timestamp with time zone, closed_by uuid, close_evidence_urls text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.has_permission('cash-management') then
    raise exception 'Permission denied';
  end if;

  return query
  select
    session.id,
    session.cashier_id,
    session.cashier_name,
    session.expected_opening_cash,
    session.opening_cash,
    session.opening_variance,
    session.opening_evidence_urls,
    case when session.status = 'closed' then session.cash_sales else sales.cash_sales end,
    case when session.status = 'closed' then session.transfer_sales else sales.transfer_sales end,
    case
      when session.status = 'closed' then session.expected_cash + session.cash_adjustment
      else session.opening_cash + sales.cash_sales + session.cash_adjustment
    end,
    session.counted_cash,
    session.variance,
    session.status,
    session.opened_at,
    session.closed_at,
    session.closed_by,
    session.close_evidence_urls
  from public.cash_drawer_sessions session
  cross join lateral (
    select
      coalesce(sum(o.total) filter (where o.status = 'paid' and o.payment_method = 'cash'), 0)::numeric as cash_sales,
      coalesce(sum(o.total) filter (where o.status = 'paid' and o.payment_method = 'transfer'), 0)::numeric as transfer_sales
    from public.orders o
    where o.cash_session_id = session.id
  ) sales
  where (
      session.status = 'open'
      or public.has_permission('cash-management.history.view')
    )
    and (
      session.cashier_id = auth.uid()
      or public.has_permission('cash-management.view-all')
    )
  order by session.opened_at desc
  limit least(greatest(coalesce(limit_input, 100), 1), 500);
end;
$$;


--
-- Name: open_cash_drawer(numeric, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_cash_drawer(opening_cash_input numeric, evidence_urls_input text[] DEFAULT '{}'::text[]) RETURNS public.cash_drawer_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cashier_name_value text;
  expected_opening_cash_value numeric(12, 2);
  is_first_session_value boolean;
  opening_variance_value numeric(12, 2);
  session_record public.cash_drawer_sessions;
begin
  if auth.uid() is null or not public.has_permission('cash-management.session.open') then
    raise exception 'Permission denied';
  end if;

  if opening_cash_input is null or opening_cash_input < 0 then
    raise exception 'Opening cash cannot be negative';
  end if;

  perform pg_advisory_xact_lock(417902113);

  if exists (
    select 1
    from public.cash_drawer_sessions
    where status = 'open'
      and public.requires_cash_reconciliation(cashier_id)
  ) then
    raise exception 'Cash drawer is already open';
  end if;

  update public.cash_drawer_sessions supporting_session
  set
    cash_sales = coalesce((
      select sum(pos_order.total)
      from public.orders pos_order
      where pos_order.cash_session_id = supporting_session.id
        and pos_order.status = 'paid'
        and pos_order.payment_method = 'cash'
    ), 0),
    transfer_sales = coalesce((
      select sum(pos_order.total)
      from public.orders pos_order
      where pos_order.cash_session_id = supporting_session.id
        and pos_order.status = 'paid'
        and pos_order.payment_method = 'transfer'
    ), 0),
    expected_cash = public.current_cash_drawer_balance(),
    counted_cash = public.current_cash_drawer_balance(),
    variance = 0,
    cash_adjustment = 0,
    status = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    close_evidence_urls = '{}'
  where supporting_session.status = 'open'
    and not public.requires_cash_reconciliation(supporting_session.cashier_id);

  is_first_session_value := not exists (
    select 1 from public.cash_drawer_sessions
  );
  expected_opening_cash_value := public.current_cash_drawer_balance();
  opening_variance_value := opening_cash_input - expected_opening_cash_value;

  if opening_variance_value <> 0 then
    if not public.has_permission('cash-management.handover.override') then
      if is_first_session_value then
        raise exception 'Opening cash does not match the system balance and requires manager approval';
      end if;
      raise exception 'Opening cash does not match the previous handover balance';
    end if;

    if cardinality(coalesce(evidence_urls_input, '{}')) not between 1 and 5 then
      raise exception 'Between 1 and 5 evidence images are required when opening cash has a variance';
    end if;
  end if;

  select concat_ws(
    ' - ',
    coalesce(r.name, nullif(trim(p.role), ''), 'Nhân viên'),
    nullif(trim(p.full_name), '')
  )
  into cashier_name_value
  from public.profiles p
  left join public.app_roles r on r.id = p.role_id
  where p.id = auth.uid()
    and p.is_active = true;

  if not found then
    raise exception 'Active cashier profile is required';
  end if;

  insert into public.cash_drawer_sessions (
    cashier_id,
    cashier_name,
    expected_opening_cash,
    opening_cash,
    opening_variance,
    opening_evidence_urls
  )
  values (
    auth.uid(),
    coalesce(nullif(cashier_name_value, ''), 'Nhân viên'),
    expected_opening_cash_value,
    opening_cash_input,
    opening_variance_value,
    case when opening_variance_value = 0 then '{}' else coalesce(evidence_urls_input, '{}') end
  )
  returning * into session_record;

  return session_record;
exception
  when unique_violation then
    raise exception 'Cash drawer is already open';
end;
$$;


--
-- Name: product_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variant_id uuid NOT NULL,
    quantity integer NOT NULL,
    shelf_quantity integer DEFAULT 0 NOT NULL,
    import_date date,
    expiry_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT product_batches_check CHECK (((shelf_quantity >= 0) AND (shelf_quantity <= quantity))),
    CONSTRAINT product_batches_quantity_check CHECK ((quantity >= 0))
);


--
-- Name: receive_product_stock(uuid, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_product_stock(product_id_input uuid, quantity_input integer, import_date_input date, expiry_date_input date) RETURNS public.product_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare variant_record public.product_variants; batch_record public.product_batches;
begin
  if not public.has_permission('products.receive-stock') then raise exception 'Only admins can receive stock'; end if;
  select * into variant_record from public.product_variants where product_id=product_id_input and is_active;
  if not found then raise exception 'Product variant not found'; end if;
  if (select count(*) from public.product_variants where product_id=product_id_input and is_active)<>1 then raise exception 'Choose a SKU in Product editor for multi-variant stock'; end if;
  if quantity_input<=0 then raise exception 'Quantity must be greater than zero'; end if;
  update public.product_variants set stock_quantity=stock_quantity+quantity_input,updated_at=now() where id=variant_record.id;
  insert into public.product_batches(variant_id,quantity,import_date,expiry_date) values(variant_record.id,quantity_input,import_date_input,expiry_date_input) returning * into batch_record;
  insert into public.stock_movements(variant_id,movement_type,quantity,reason,actor_id,actor_name) values(variant_record.id,'in',quantity_input,'Receive stock',auth.uid(),coalesce((select full_name from public.profiles where id=auth.uid()),'System'));
  return batch_record;
end;
$$;


--
-- Name: receive_variant_stock(uuid, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_variant_stock(variant_id_input uuid, quantity_input integer, import_date_input date DEFAULT NULL::date, expiry_date_input date DEFAULT NULL::date) RETURNS public.product_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  variant_record public.product_variants;
  batch_record public.product_batches;
begin
  if not public.has_permission('products.receive-stock') then
    raise exception 'Permission denied for stock receipt';
  end if;
  if quantity_input <= 0 then raise exception 'Quantity must be greater than zero'; end if;

  select * into variant_record
  from public.product_variants
  where id = variant_id_input and is_active
  for update;
  if variant_record.id is null then raise exception 'Product variant not found'; end if;

  update public.product_variants
  set stock_quantity = stock_quantity + quantity_input, updated_at = now()
  where id = variant_record.id;

  insert into public.product_batches(variant_id, quantity, import_date, expiry_date)
  values(variant_record.id, quantity_input, import_date_input, expiry_date_input)
  returning * into batch_record;

  insert into public.stock_movements(variant_id,movement_type,quantity,reason,actor_id,actor_name)
  values(variant_record.id,'in',quantity_input,'Nhập kho theo SKU',auth.uid(),coalesce((select full_name from public.profiles where id=auth.uid()),'Hệ thống'));
  return batch_record;
end;
$$;


--
-- Name: record_order_print(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_order_print(order_id_input uuid) RETURNS public.orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  order_record public.orders;
begin
  if not (
    public.has_permission('orders')
    or public.has_permission('pos.checkout')
  ) then
    raise exception 'Permission denied';
  end if;

  update public.orders
  set print_count = print_count + 1
  where id = order_id_input
    and (
      public.has_permission('orders')
      or cashier_id = auth.uid()
      or public.is_admin()
    )
  returning * into order_record;

  if not found then
    raise exception 'Order not found or permission denied';
  end if;

  insert into public.order_audit_events (order_id, actor_id, event_type, details)
  values (
    order_record.id,
    auth.uid(),
    'printed',
    jsonb_build_object('print_count', order_record.print_count)
  );

  return order_record;
end;
$$;


--
-- Name: requires_cash_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requires_cash_reconciliation(user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    join public.app_roles r on r.id = p.role_id
    where p.id = user_id
      and p.is_active = true
      and r.is_active = true
      and p.role <> 'admin'
      and r.code <> 'admin'
      and not (
        user_id = auth.uid()
        and coalesce(auth.jwt() -> 'app_metadata' ->> 'role', '') = 'admin'
      )
      and 'cash-management.reconciliation.required' = any(coalesce(r.permissions, '{}'))
  );
$$;


--
-- Name: reserve_variant_stock(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_variant_stock(variant_id_input uuid, quantity_input integer, batch_id_input uuid DEFAULT NULL::uuid) RETURNS public.product_variants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.product_variants; b public.product_batches;
begin
  if quantity_input <= 0 then raise exception 'Quantity must be positive'; end if;
  select * into v from public.product_variants where id = variant_id_input and is_active for update;
  if v.id is null then raise exception 'Product variant is not available'; end if;
  if v.stock_quantity < quantity_input or v.shelf_quantity < quantity_input then
    raise exception 'Insufficient stock for selected product variant';
  end if;
  if batch_id_input is not null then
    select * into b from public.product_batches where id = batch_id_input and variant_id = v.id for update;
    if b.id is null or b.quantity < quantity_input or b.shelf_quantity < quantity_input then
      raise exception 'Insufficient stock for selected batch';
    end if;
    update public.product_batches set quantity=quantity-quantity_input, shelf_quantity=shelf_quantity-quantity_input where id=b.id;
  end if;
  update public.product_variants set stock_quantity=stock_quantity-quantity_input,
    shelf_quantity=shelf_quantity-quantity_input, updated_at=now() where id=v.id returning * into v;
  return v;
end;
$$;


--
-- Name: save_product_engine(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_product_engine(payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare product_id_value uuid; attribute jsonb; value_row jsonb; variant jsonb; image_row jsonb; specification jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if nullif(payload->>'id','') is null then
    if not public.has_permission('products.create') then raise exception 'Permission denied for product create'; end if;
  elsif exists(select 1 from public.products where id=(payload->>'id')::uuid) then
    if not public.has_permission('products.update') then raise exception 'Permission denied for product update'; end if;
  elsif not public.has_permission('products.create') then
    raise exception 'Permission denied for product create';
  end if;
  product_id_value := coalesce(nullif(payload->>'id','')::uuid, gen_random_uuid());
  insert into public.products(id,product_type_id,category_id,name,slug,description,status,is_reward,reward_points_cost,seo_title,seo_description)
  values(product_id_value,nullif(payload->>'product_type_id','')::uuid,nullif(payload->>'category_id','')::uuid,
    trim(payload->>'name'),trim(payload->>'slug'),nullif(payload->>'description',''),coalesce(payload->>'status','draft'),
    coalesce((payload->>'is_reward')::boolean,false),coalesce((payload->>'reward_points_cost')::integer,0),nullif(payload->>'seo_title',''),nullif(payload->>'seo_description',''))
  on conflict(id) do update set product_type_id=excluded.product_type_id,category_id=excluded.category_id,name=excluded.name,
    slug=excluded.slug,description=excluded.description,status=excluded.status,is_reward=excluded.is_reward,
    reward_points_cost=excluded.reward_points_cost,seo_title=excluded.seo_title,seo_description=excluded.seo_description,updated_at=now();

  delete from public.product_specifications where product_id=product_id_value;
  for specification in select value from jsonb_array_elements(coalesce(payload->'specifications','[]')) loop
    insert into public.product_specifications(id,product_id,attribute_id,name,code,data_type,input_type,unit,value,is_required,sort_order)
    values(coalesce(nullif(specification->>'id','')::uuid,gen_random_uuid()),product_id_value,nullif(specification->>'attribute_id','')::uuid,
      specification->>'name',specification->>'code',specification->>'data_type',specification->>'input_type',nullif(specification->>'unit',''),
      coalesce(specification->'value','null'::jsonb),coalesce((specification->>'is_required')::boolean,false),coalesce((specification->>'sort_order')::integer,0));
  end loop;

  delete from public.product_images where product_id=product_id_value;
  for attribute in select value from jsonb_array_elements(coalesce(payload->'variant_attributes','[]')) loop
    insert into public.product_variant_attributes(id,product_id,source_attribute_id,name,code,data_type,display_type,is_required,sort_order)
    values((attribute->>'id')::uuid,product_id_value,nullif(attribute->>'source_attribute_id','')::uuid,attribute->>'name',attribute->>'code',
      coalesce(attribute->>'data_type','option'),coalesce(attribute->>'display_type','text_button'),coalesce((attribute->>'is_required')::boolean,true),coalesce((attribute->>'sort_order')::integer,0))
    on conflict(id) do update set source_attribute_id=excluded.source_attribute_id,name=excluded.name,code=excluded.code,data_type=excluded.data_type,display_type=excluded.display_type,is_required=excluded.is_required,sort_order=excluded.sort_order,updated_at=now();
    for value_row in select value from jsonb_array_elements(coalesce(attribute->'values','[]')) loop
      insert into public.product_variant_values(id,variant_attribute_id,label,value,metadata,sort_order,is_active)
      values((value_row->>'id')::uuid,(attribute->>'id')::uuid,value_row->>'label',value_row->>'value',coalesce(value_row->'metadata','{}'),
        coalesce((value_row->>'sort_order')::integer,0),coalesce((value_row->>'is_active')::boolean,true))
      on conflict(id) do update set label=excluded.label,value=excluded.value,metadata=excluded.metadata,sort_order=excluded.sort_order,is_active=excluded.is_active,updated_at=now();
    end loop;
  end loop;
  delete from public.product_variants pv where pv.product_id=product_id_value and not exists(
    select 1 from jsonb_array_elements(coalesce(payload->'variants','[]')) item where nullif(item->>'id','')::uuid=pv.id
  );
  update public.product_variants set is_default=false where product_id=product_id_value;
  for variant in select value from jsonb_array_elements(coalesce(payload->'variants','[]')) loop
    delete from public.variant_value_links where variant_id=(variant->>'id')::uuid;
    insert into public.product_variants(id,product_id,sku,barcode,base_price,compare_at_price,cost_price,stock_quantity,shelf_quantity,weight,is_default,is_active)
    values((variant->>'id')::uuid,product_id_value,variant->>'sku',nullif(variant->>'barcode',''),
      coalesce((variant->>'base_price')::numeric,0),nullif(variant->>'compare_at_price','')::numeric,coalesce((variant->>'cost_price')::numeric,0),
      coalesce((variant->>'stock_quantity')::integer,0),coalesce((variant->>'shelf_quantity')::integer,0),nullif(variant->>'weight','')::numeric,
      coalesce((variant->>'is_default')::boolean,false),coalesce((variant->>'is_active')::boolean,true))
    on conflict(id) do update set sku=excluded.sku,barcode=excluded.barcode,base_price=excluded.base_price,compare_at_price=excluded.compare_at_price,cost_price=excluded.cost_price,stock_quantity=excluded.stock_quantity,shelf_quantity=excluded.shelf_quantity,weight=excluded.weight,is_default=excluded.is_default,is_active=excluded.is_active,updated_at=now();
    insert into public.variant_value_links(variant_id,variant_value_id,variant_attribute_id)
    select (variant->>'id')::uuid,
      vv.id,vv.variant_attribute_id from jsonb_array_elements_text(coalesce(variant->'value_ids','[]')) ids(id)
      join public.product_variant_values vv on vv.id=ids.id::uuid;
    if nullif(variant->>'image_url','') is not null then
      insert into public.product_images(product_id,variant_id,image_url,cloudinary_public_id,is_primary)
      select product_id_value,pv.id,variant->>'image_url',nullif(variant->>'cloudinary_public_id',''),true
      from public.product_variants pv where pv.product_id=product_id_value and pv.sku=variant->>'sku';
    end if;
  end loop;
  delete from public.product_variants pv where pv.product_id=product_id_value and not exists(
    select 1 from jsonb_array_elements(coalesce(payload->'variants','[]')) item where nullif(item->>'id','')::uuid=pv.id
  );
  delete from public.product_variant_values vv using public.product_variant_attributes va where vv.variant_attribute_id=va.id and va.product_id=product_id_value and not exists(
    select 1 from jsonb_array_elements(coalesce(payload->'variant_attributes','[]')) a,
      jsonb_array_elements(coalesce(a->'values','[]')) v where nullif(v->>'id','')::uuid=vv.id
  );
  delete from public.product_variant_attributes va where va.product_id=product_id_value and not exists(
    select 1 from jsonb_array_elements(coalesce(payload->'variant_attributes','[]')) a where nullif(a->>'id','')::uuid=va.id
  );
  for image_row in select value from jsonb_array_elements(coalesce(payload->'images','[]')) loop
    if nullif(image_row->>'variant_id','') is null and nullif(image_row->>'variant_value_id','') is null then
      insert into public.product_images(id,product_id,image_url,cloudinary_public_id,alt_text,sort_order,is_primary)
      values(coalesce(nullif(image_row->>'id','')::uuid,gen_random_uuid()),product_id_value,image_row->>'image_url',nullif(image_row->>'cloudinary_public_id',''),
        nullif(image_row->>'alt_text',''),coalesce((image_row->>'sort_order')::integer,0),coalesce((image_row->>'is_primary')::boolean,false));
    end if;
  end loop;
  if not exists(select 1 from public.product_variants where product_id=product_id_value) then
    insert into public.product_variants(product_id,sku,is_default) values(product_id_value,'DEFAULT-'||upper(substr(replace(product_id_value::text,'-',''),1,12)),true);
  end if;
  return product_id_value;
end;
$$;


