--
-- Name: set_app_role_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_app_role_active(role_id_input uuid, is_active_input boolean) RETURNS public.app_roles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  role_record public.app_roles;
begin
  if not public.has_permission('roles.toggle-active') then
    raise exception 'Permission denied';
  end if;

  update public.app_roles
  set is_active = is_active_input
  where id = role_id_input
    and code <> 'admin'
  returning * into role_record;

  if not found then
    raise exception 'Role is not available';
  end if;

  return role_record;
end;
$$;


--
-- Name: set_product_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_product_active(product_id_input uuid, is_active_input boolean) RETURNS public.products
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result public.products;
begin
  if auth.uid() is null or not public.has_permission('products.toggle-active') then
    raise exception 'Permission denied for product status update';
  end if;
  update public.products
  set status=case when is_active_input then 'active' else 'inactive' end, updated_at=now()
  where id=product_id_input and deleted_at is null
  returning * into result;
  if result.id is null then raise exception 'Product not found'; end if;
  return result;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: soft_delete_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_product(product_id_input uuid) RETURNS public.products
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.products;
begin
  if not public.has_permission('products.delete') then
    raise exception 'Permission denied for product delete';
  end if;
  update public.products
  set status = 'inactive', deleted_at = now(), updated_at = now()
  where id = product_id_input
  returning * into result;
  return result;
end;
$$;


--
-- Name: submit_attendance_cash_check(uuid, numeric, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_attendance_cash_check(attendance_record_id_input uuid, actual_cash_input numeric, evidence_urls_input text[] DEFAULT '{}'::text[]) RETURNS public.cash_drawer_checks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  check_record public.cash_drawer_checks;
  opened_session public.cash_drawer_sessions;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.has_permission('attendance.clock') then
    raise exception 'Permission denied';
  end if;

  if actual_cash_input is null or actual_cash_input < 0 then
    raise exception 'Actual cash is required';
  end if;

  select *
  into check_record
  from public.cash_drawer_checks
  where attendance_record_id = attendance_record_id_input
    and employee_id = auth.uid()
  for update;

  if not found then
    raise exception 'Cash drawer check is not available';
  end if;

  if check_record.checked_at is not null then
    return check_record;
  end if;

  -- Recheck at submit time so an invoice created after opening the modal is
  -- included in both the displayed drawer and the reconciliation.
  check_record.expected_cash := public.current_cash_drawer_balance();

  if actual_cash_input <> check_record.expected_cash
    and cardinality(coalesce(evidence_urls_input, '{}')) not between 1 and 5 then
    raise exception 'Between 1 and 5 evidence images are required when cash does not match';
  end if;

  select *
  into opened_session
  from public.cash_drawer_sessions
  where status = 'open'
    and public.requires_cash_reconciliation(cashier_id)
  order by opened_at desc, id desc
  limit 1
  for update;

  if found then
    if opened_session.cashier_id <> auth.uid() then
      raise exception 'Previous cash drawer session must be closed before reconciliation';
    end if;
    -- Retrying the confirmation for the employee's own open drawer is safe;
    -- do not attempt to create a second session.
  else
    select *
    into opened_session
    from public.open_cash_drawer(actual_cash_input, evidence_urls_input);
  end if;

  update public.cash_drawer_checks
  set
    cash_session_id = opened_session.id,
    expected_cash = check_record.expected_cash,
    actual_cash = actual_cash_input,
    is_match = (actual_cash_input = check_record.expected_cash),
    evidence_urls = case when actual_cash_input = check_record.expected_cash then '{}' else coalesce(evidence_urls_input, '{}') end,
    checked_at = now()
  where id = check_record.id
  returning * into check_record;

  return check_record;
end;
$$;


--
-- Name: submit_inventory_audit(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_inventory_audit(staff_name_input text, lines_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare audit_id_value uuid; line jsonb; variant_record public.product_variants;
begin
  if not public.has_permission('inventory.submit') then raise exception 'Permission denied'; end if;
  insert into public.inventory_audits(created_by,staff_name)
  values(auth.uid(),left(trim(staff_name_input),160)) returning id into audit_id_value;
  for line in select value from jsonb_array_elements(lines_input) loop
    select * into variant_record from public.product_variants
    where id=(line->>'variant_id')::uuid and is_active;
    if variant_record.id is null then raise exception 'Product variant not found'; end if;
    insert into public.inventory_audit_lines(audit_id,variant_id,product_name,sku,counted)
    values(audit_id_value,variant_record.id,line->>'product_name',variant_record.sku,(line->>'counted')::integer);
  end loop;
  return audit_id_value;
end;
$$;


