    CONSTRAINT promotion_scopes_scope_type_check CHECK ((scope_type = ANY (ARRAY['all'::text, 'category'::text, 'product'::text, 'variant'::text])))
);


--
-- Name: promotions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    code text,
    trigger_type text NOT NULL,
    discount_type text NOT NULL,
    discount_value numeric(12,2) DEFAULT 0 NOT NULL,
    max_discount_amount numeric(12,2),
    start_at timestamp with time zone,
    end_at timestamp with time zone,
    total_usage_limit integer,
    usage_per_customer integer,
    priority integer DEFAULT 0 NOT NULL,
    is_stackable boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promotions_check CHECK ((((trigger_type = 'coupon'::text) AND (NULLIF(TRIM(BOTH FROM code), ''::text) IS NOT NULL)) OR (trigger_type = 'automatic'::text))),
    CONSTRAINT promotions_check1 CHECK (((end_at IS NULL) OR (start_at IS NULL) OR (end_at > start_at))),
    CONSTRAINT promotions_check2 CHECK (((discount_type <> 'percentage'::text) OR (discount_value <= (100)::numeric))),
    CONSTRAINT promotions_discount_type_check CHECK ((discount_type = ANY (ARRAY['percentage'::text, 'fixed_amount'::text, 'free_shipping'::text]))),
    CONSTRAINT promotions_discount_value_check CHECK ((discount_value >= (0)::numeric)),
    CONSTRAINT promotions_max_discount_amount_check CHECK (((max_discount_amount IS NULL) OR (max_discount_amount >= (0)::numeric))),
    CONSTRAINT promotions_total_usage_limit_check CHECK (((total_usage_limit IS NULL) OR (total_usage_limit > 0))),
    CONSTRAINT promotions_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['automatic'::text, 'coupon'::text]))),
    CONSTRAINT promotions_usage_per_customer_check CHECK (((usage_per_customer IS NULL) OR (usage_per_customer > 0)))
);


