--
-- Name: cash_drawer_checks Attendance and cash managers can read drawer checks; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Attendance and cash managers can read drawer checks" ON public.cash_drawer_checks FOR SELECT USING ((((employee_id = auth.uid()) AND public.has_permission('attendance.clock'::text) AND (EXISTS ( SELECT 1
   FROM public.attendance_records attendance
  WHERE ((attendance.id = cash_drawer_checks.attendance_record_id) AND (attendance.clock_out_at IS NULL))))) OR public.has_permission('attendance.history.view-all'::text) OR (public.has_permission('cash-management.history.view'::text) AND ((employee_id = auth.uid()) OR public.has_permission('cash-management.view-all'::text)))));


